import pathlib,json,hashlib,importlib.util,collections,numpy as np
R=pathlib.Path(r'C:\tmp\disdex-d126-crossrunner-research-20261126')
SRC=R/'y06_r3_bear_retest_research_v2.py';prior=R/'Y06_R11_FLOW_BARRIER_RESULTS_20261127.json'
sp=importlib.util.spec_from_file_location('r3',SRC);r3=importlib.util.module_from_spec(sp);sp.loader.exec_module(r3)
bt=r3.bt;H=bt.H;M=bt.M
P=R/'Y06_R12_ABSORPTION_PROTOCOL_20261127.json';O=R/'Y06_R12_ABSORPTION_RESULTS_20261127.json'
assert not P.exists() and not O.exists()
p={'status':'RESEARCH_ONLY_POST_R11_EXPLORATORY','parent_sha256':hashlib.sha256(prior.read_bytes()).hexdigest(),'cohort':'R11 original FLOW_ABSORB selected intentions unchanged; no new selection using outcomes. Compare LONG/SHORT separately and same-direction BTC24h/72h gate. Compare contrary BTC24h/72h as diagnostic only.','arms':['ALL','LONG_ONLY','SHORT_ONLY','MARKET_ALIGNED','MARKET_OPPOSED','SHORT_ALIGNED','LONG_ALIGNED'],'exit':'Original R11 TP8 STOP8 /48h and TIME48 STOP8; new TP5 STOP4 comparison. Include price-gap adverse fill, STOP first, original gross .30 2 slots 12h cooldown. 10/30bps; no funding.','control':'32 seed fixed randomized other symbols available at same timestamp with identical individual R3 data QA, closed H1 72h finite, same side, same holding horizon, no future candidate filtering except priced control paths. All arms including ALL with at least 2 positive splits. All periods already inspected.','limitations':'Direction and market gate post hoc exploration; no untouched periods; matched controls only test symbol selection conditional on original time, not timing edge.'}
P.write_text(json.dumps(p,indent=2),encoding='utf8')
d=json.loads(prior.read_text(encoding='utf8'));sig=d['selected']['FLOW_ABSORB'];btc,_=bt.data('BTC','1h');hs={};ms={};qa={}
for sym in bt.SYMS[1:]:
 h,_=bt.data(sym,'1h');m,_=bt.data(sym,'5m');hs[sym]=h;ms[sym]=m;qa[sym]=r3.prepare_qa(h,m)[0]
 print('LOAD',sym,flush=True)
def endof(per):return bt.PERIODS[per][1] if per!='FORWARD_INSPECTED' else bt.T('2026-11-26T00:00:00Z')
def trade(x,tp,sl):
 m=ms[x['symbol']];k=(x['entryTs']-bt.MS)//M;j=k+576;side=x['side']
 if x['entryTs']+48*H>=endof(x['period']) or k<0 or j>=len(m) or not np.isfinite(m[k:j+1,:4]).all():return None
 ep=float(m[k,0]);stop=ep*(1-side*sl);target=ep*(1+side*tp) if tp else None
 hi=m[k:j,1];lo=m[k:j,2];sh=np.flatnonzero(lo<=stop if side==1 else hi>=stop);th=np.flatnonzero(hi>=target if side==1 else lo<=target) if tp else []
 si=int(sh[0]) if len(sh) else 576;ti=int(th[0]) if len(th) else 576
 xp=float(m[j,0]);et=bt.MS+j*M;reason='TIME48'
 if si<=ti and si<576:
  q=k+si;xp=float(min(m[q,0],stop) if side==1 else max(m[q,0],stop));et=bt.MS+(q+1)*M;reason='HARD_STOP8' if sl==.08 else 'EARLY_STOP4'
 elif ti<576:
  q=k+ti;xp=float(target);et=bt.MS+(q+1)*M;reason='TARGET'
 return {**x,'direction':'LONG' if side==1 else 'SHORT','entry':ep,'exitPrice':xp,'exitTs':et,'rawReturn':side*(xp/ep-1),'exitReason':reason}
def compact(w):return {k:v for k,v in w.items() if k!='accepted'}
arms=collections.defaultdict(list)
for x in sig:
 i=(x['entryTs']-bt.HS)//H;side=x['side']
 if i<73 or not np.isfinite(btc[i-73:i,3]).all():continue
 b24=btc[i-1,3]/btc[i-25,3]-1;b72=btc[i-1,3]/btc[i-73,3]-1
 same=side*b24>0 and side*b72>0;opp=side*b24<0 and side*b72<0
 arms['ALL'].append(x);arms['LONG_ONLY' if side==1 else 'SHORT_ONLY'].append(x)
 if same:arms['MARKET_ALIGNED'].append(x);arms['LONG_ALIGNED' if side==1 else 'SHORT_ALIGNED'].append(x)
 if opp:arms['MARKET_OPPOSED'].append(x)
rng=np.random.default_rng(2026112713);out={}
for arm in p['arms']:
 for ex,tp,sl in [('TP8_STOP8',.08,.08),('TIME48_STOP8',0,.08),('TP5_STOP4',.05,.04)]:
  key=arm+'/'+ex;out[key]={}
  for per in bt.PERIODS:
   a=[x for x in arms[arm] if x['period']==per and x['entryTs']+48*H<endof(per)];z=[q for x in a if(q:=trade(x,tp,sl)) is not None]
   w={str(f):compact(bt.wallet(z,per,f,ms)) for f in (10,30)}
   out[key][per]={'intentions':len(a),'unpriced':len(a)-len(z),'wallet':w,'mean_net_pct':float(100*np.mean([q['rawReturn']-.003 for q in z])) if z else None}
  print('BT',key,[(round(v['wallet']['30']['terminal_jpy']),round(v['wallet']['30']['max_dd_pct'],2),v['wallet']['30']['n'],v['wallet']['30']['wins']) for v in out[key].values()],flush=True)
  if arm!='ALL' and sum(v['wallet']['30']['terminal_jpy']>10000 for v in out[key].values())<2:continue
  for per,rec in out[key].items():
   pairs=[]
   for x in arms[arm]:
    if x['period']!=per:continue
    z=trade(x,tp,sl)
    if z is None:continue
    i=(x['entryTs']-bt.HS)//H
    a=[q for s,h in hs.items() if s!=x['symbol'] and qa[s][i] and np.isfinite(h[i-73:i,:5]).all() and (q:=trade({**x,'symbol':s},tp,sl)) is not None]
    if len(a)>=2:pairs.append((z,a))
   aw=compact(bt.wallet([x for x,a in pairs],per,30,ms));ds=[compact(bt.wallet([a[rng.integers(len(a))] for x,a in pairs],per,30,ms)) for _ in range(32)];vals=[v['terminal_jpy'] for v in ds]
   rec['matched']={'n_pairs':len(pairs),'actual':aw,'mean_terminal':float(np.mean(vals)),'beats':sum(aw['terminal_jpy']>v for v in vals),'delta_pp':float(np.mean([100*(x['rawReturn']-np.mean([q['rawReturn'] for q in a])) for x,a in pairs])) if pairs else None,'draws':ds}
   print('MATCH',key,per,len(pairs),round(aw['terminal_jpy']),round(np.mean(vals)),rec['matched']['beats'],rec['matched']['delta_pp'],flush=True)
O.write_text(json.dumps({'protocol':p,'protocol_sha256':hashlib.sha256(P.read_bytes()).hexdigest(),'results':out},indent=2,allow_nan=False),encoding='utf8')
print('SAVED',hashlib.sha256(O.read_bytes()).hexdigest(),flush=True)
